package com.example.platform.studio.diff;

import com.example.platform.studio.camera.CameraPlanVersion;import com.example.platform.studio.directorintent.DirectorIntentVersion;import com.example.platform.studio.scene.SceneVersion;import com.example.platform.studio.screenplay.*;import com.example.platform.studio.serialization.CanonicalJson;import com.example.platform.studio.shot.ShotVersion;import com.example.platform.studio.shotplan.ShotPlanVersion;import com.example.platform.studio.shotscene.ShotSceneVersion;import com.example.platform.studio.storyboard.StoryboardVersion;import java.nio.charset.StandardCharsets;import java.util.*;
public record StudioSemanticDiff(List<SemanticChange>changes){public StudioSemanticDiff{if(changes==null)throw new IllegalArgumentException("changes required");var sorted=new ArrayList<>(changes);sorted.sort(SemanticChange.CANONICAL_ORDER);changes=List.copyOf(sorted);}public static int supportedAggregateTypeCount(){return 8;}
public static StudioSemanticDiff between(Object a,Object b){if(a==null||b==null||a.getClass()!=b.getClass())throw new IllegalArgumentException("semantic diff requires the same aggregate type");if(a instanceof ScreenplayVersion x)return between(x,(ScreenplayVersion)b);if(a instanceof SceneVersion x)return between(x,(SceneVersion)b);if(a instanceof ShotVersion x)return between(x,(ShotVersion)b);if(a instanceof ShotPlanVersion x)return between(x,(ShotPlanVersion)b);if(a instanceof DirectorIntentVersion x)return between(x,(DirectorIntentVersion)b);if(a instanceof CameraPlanVersion x)return between(x,(CameraPlanVersion)b);if(a instanceof StoryboardVersion x)return between(x,(StoryboardVersion)b);if(a instanceof ShotSceneVersion x)return between(x,(ShotSceneVersion)b);throw new IllegalArgumentException("unsupported aggregate type");}
public static StudioSemanticDiff between(ScreenplayVersion a,ScreenplayVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());var am=new LinkedHashMap<String,ScreenplayElement>();a.elements().forEach(e->am.put(e.id().value(),e));var bm=new LinkedHashMap<String,ScreenplayElement>();b.elements().forEach(e->bm.put(e.id().value(),e));for(var id:am.keySet())if(!bm.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REMOVED,TypedPath.of("elements",id),am.get(id).canonicalJson(),null));for(var id:bm.keySet())if(!am.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.ADDED,TypedPath.of("elements",id),null,bm.get(id).canonicalJson()));for(var id:am.keySet())if(bm.containsKey(id)&&!am.get(id).canonicalJson().equals(bm.get(id).canonicalJson()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.FIELD_CHANGED,TypedPath.of("elements",id),am.get(id).canonicalJson(),bm.get(id).canonicalJson()));var ao=a.elements().stream().map(e->e.id().value()).toList();var bo=b.elements().stream().map(e->e.id().value()).toList();if(!ao.equals(bo))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REORDERED,TypedPath.of("elements","order"),ao.toString(),bo.toString()));return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(SceneVersion a,SceneVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());repin(changes,"screenplayPin",a.screenplayPin(),b.screenplayPin());field(changes,"headingElementId",a.headingElementId().value(),b.headingElementId().value());field(changes,"synopsis",a.synopsis(),b.synopsis());field(changes,"narrativePurpose",a.narrativePurpose(),b.narrativePurpose());return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(ShotVersion a,ShotVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());repin(changes,"scenePin",a.scenePin(),b.scenePin());field(changes,"description",a.description(),b.description());field(changes,"subjectActionIntent",a.subjectActionIntent(),b.subjectActionIntent());field(changes,"continuityIntent",a.continuityIntent(),b.continuityIntent());field(changes,"planningDuration",mediaTime(a.planningDuration()),mediaTime(b.planningDuration()));repin(changes,"directorIntentPin",a.directorIntentPin(),b.directorIntentPin());repin(changes,"cameraPlanPin",a.cameraPlanPin(),b.cameraPlanPin());return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(ShotPlanVersion a,ShotPlanVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());if(!a.screenplayPin().equals(b.screenplayPin()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REPINNED,TypedPath.of("screenplayPin"),a.screenplayPin().canonicalJson(),b.screenplayPin().canonicalJson()));if(!a.scenePin().equals(b.scenePin()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REPINNED,TypedPath.of("scenePin"),a.scenePin().canonicalJson(),b.scenePin().canonicalJson()));var am=new LinkedHashMap<String,String>();a.shotPins().forEach(p->am.put(p.aggregateId().value(),p.canonicalJson()));var bm=new LinkedHashMap<String,String>();b.shotPins().forEach(p->bm.put(p.aggregateId().value(),p.canonicalJson()));for(var id:am.keySet())if(!bm.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REMOVED,TypedPath.of("shots",id),am.get(id),null));for(var id:bm.keySet())if(!am.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.ADDED,TypedPath.of("shots",id),null,bm.get(id)));for(var id:am.keySet())if(bm.containsKey(id)&&!am.get(id).equals(bm.get(id)))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REPINNED,TypedPath.of("shots",id),am.get(id),bm.get(id)));var ao=a.shotPins().stream().map(p->p.aggregateId().value()).toList();var bo=b.shotPins().stream().map(p->p.aggregateId().value()).toList();if(!ao.equals(bo))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REORDERED,TypedPath.of("shots","order"),ao.toString(),bo.toString()));return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(DirectorIntentVersion a,DirectorIntentVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());field(changes,"emphasis",a.emphasis().name(),b.emphasis().name());field(changes,"emotionalTone",a.emotionalTone().name(),b.emotionalTone().name());field(changes,"cameraMovementIntent",a.movementIntent().name(),b.movementIntent().name());field(changes,"lightingMood",a.lightingMood().name(),b.lightingMood().name());field(changes,TypedPath.of("annotations","semantics"),CanonicalJson.array(a.annotations().stream().map(CanonicalJson::quote).toList()),CanonicalJson.array(b.annotations().stream().map(CanonicalJson::quote).toList()));return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(CameraPlanVersion a,CameraPlanVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());if(!a.pose().canonicalJson().equals(b.pose().canonicalJson()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.TRANSFORM_CHANGED,TypedPath.of("pose"),a.pose().canonicalJson(),b.pose().canonicalJson()));field(changes,"projection",a.projection().name(),b.projection().name());field(changes,"framing",a.framing().name(),b.framing().name());field(changes,"targetIntent",a.targetIntent().name(),b.targetIntent().name());field(changes,"optics",a.optics().canonicalJson(),b.optics().canonicalJson());field(changes,"imagingIntent",a.imagingIntent().canonicalJson(),b.imagingIntent().canonicalJson());repin(changes,"shotPin",a.shotPin(),b.shotPin());repin(changes,"shotPlanPin",a.shotPlanPin(),b.shotPlanPin());repin(changes,"directorIntentPin",a.directorIntentPin(),b.directorIntentPin());var ak=CanonicalJson.array(a.keyframes().stream().map(com.example.platform.studio.camera.CameraKeyframe::canonicalJson).toList());var bk=CanonicalJson.array(b.keyframes().stream().map(com.example.platform.studio.camera.CameraKeyframe::canonicalJson).toList());field(changes,TypedPath.of("keyframes","semantics"),ak,bk);return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(StoryboardVersion a,StoryboardVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());var am=new LinkedHashMap<String,String>();a.panels().forEach(p->am.put(p.id().value(),p.canonicalJson()));var bm=new LinkedHashMap<String,String>();b.panels().forEach(p->bm.put(p.id().value(),p.canonicalJson()));for(var id:am.keySet())if(!bm.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REMOVED,TypedPath.of("panels",id),am.get(id),null));for(var id:bm.keySet())if(!am.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.ADDED,TypedPath.of("panels",id),null,bm.get(id)));for(var id:am.keySet())if(bm.containsKey(id)&&!am.get(id).equals(bm.get(id)))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.FIELD_CHANGED,TypedPath.of("panels",id),am.get(id),bm.get(id)));var ao=a.panels().stream().map(p->p.id().value()).toList();var bo=b.panels().stream().map(p->p.id().value()).toList();if(!ao.equals(bo))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REORDERED,TypedPath.of("panels","order"),ao.toString(),bo.toString()));return new StudioSemanticDiff(changes);}
public static StudioSemanticDiff between(ShotSceneVersion a,ShotSceneVersion b){same(a.id(),b.id());var changes=new ArrayList<SemanticChange>();parent(changes,a.parentVersionId(),b.parentVersionId());var am=new LinkedHashMap<String,com.example.platform.studio.shotscene.SceneElement>();a.elements().forEach(e->am.put(e.id().value(),e));var bm=new LinkedHashMap<String,com.example.platform.studio.shotscene.SceneElement>();b.elements().forEach(e->bm.put(e.id().value(),e));for(var id:am.keySet())if(!bm.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REMOVED,TypedPath.of("elements",id),am.get(id).canonicalJson(),null));for(var id:bm.keySet())if(!am.containsKey(id))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.ADDED,TypedPath.of("elements",id),null,bm.get(id).canonicalJson()));for(var id:am.keySet())if(bm.containsKey(id)){var ae=am.get(id);var be=bm.get(id);if(!ae.localTransform().canonicalJson().equals(be.localTransform().canonicalJson()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.TRANSFORM_CHANGED,TypedPath.of("elements",id,"transform"),ae.localTransform().canonicalJson(),be.localTransform().canonicalJson()));else if(!ae.canonicalJson().equals(be.canonicalJson()))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.FIELD_CHANGED,TypedPath.of("elements",id),ae.canonicalJson(),be.canonicalJson()));}var ao=a.elements().stream().map(e->e.id().value()).toList();var bo=b.elements().stream().map(e->e.id().value()).toList();if(!ao.equals(bo))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REORDERED,TypedPath.of("elements","order"),ao.toString(),bo.toString()));return new StudioSemanticDiff(changes);}
private static void same(Object a,Object b){if(a==null||!a.equals(b))throw new IllegalArgumentException("semantic diff requires exact versions of the same aggregate");}
private static void parent(List<SemanticChange>changes,Object a,Object b){if(!Objects.equals(a,b))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.PARENT_CHANGED,TypedPath.of("parentVersionId"),a==null?null:a.toString(),b==null?null:b.toString()));}
private static void field(List<SemanticChange>changes,String path,String a,String b){field(changes,TypedPath.of(path),a,b);}
private static void field(List<SemanticChange>changes,TypedPath path,String a,String b){if(!Objects.equals(a,b))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.FIELD_CHANGED,path,a,b));}
private static void repin(List<SemanticChange>changes,String path,com.example.platform.studio.reference.StudioVersionPin<?,?>a,com.example.platform.studio.reference.StudioVersionPin<?,?>b){if(!Objects.equals(a,b))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.REPINNED,TypedPath.of(path),a==null?null:a.canonicalJson(),b==null?null:b.canonicalJson()));}
private static String mediaTime(com.example.platform.shared.time.MediaTime value){return CanonicalJson.object(Map.of("ticks",Long.toString(value.ticks()),"timeScale",Long.toString(value.timeScale())));}
private static StudioSemanticDiff generic(Object pa,Object pb,byte[]a,byte[]b,String root){var changes=new ArrayList<SemanticChange>();parent(changes,pa,pb);if(!Arrays.equals(a,b))changes.add(SemanticChange.changed(SemanticChange.ChangeKind.FIELD_CHANGED,TypedPath.of(root,"semantics"),new String(a,StandardCharsets.UTF_8),new String(b,StandardCharsets.UTF_8)));return new StudioSemanticDiff(changes);}
}
